-- PostgreSQL 15+: enforce one variant per garment, size and color even when
-- size or color is NULL. The index generated by @@unique remains in place.
CREATE UNIQUE INDEX "VariantePrenda_prendaId_talle_color_nulls_not_distinct_key"
ON "VariantePrenda" ("prendaId", "talle", "color") NULLS NOT DISTINCT;
